const read = (rev, path) => cp.execFileSync('git', ['show', rev + ':apps/roam/src/' + path], { cwd: repo, encoding: 'utf8' });
const evaluate = (source, deps = {}) => {
  const context = { ...deps, exports: {}, module: {exports: {}}, console: {log() {}, warn() {}}, require: deps.require || req };
  vm.runInNewContext(esbuild.transformSync(source, {loader: 'ts', format: 'cjs', target: 'es2020'}).code, context);
  return context.module.exports;
};
const extract = (source, name, nextName) => {
  const start = source.indexOf('export const ' + name + ' =');
  assert(start >= 0, name);
  const end = nextName ? source.indexOf('export const ' + nextName + ' =', start + 1) : source.length;
  assert(end > start, nextName);
  return source.slice(start, end);
};
const defaults = evaluate(read('35ac77ee', 'components/settings/data/defaultRelationsBlockProps.ts')).default;
