text(await tools.exec_command({cmd:"cat > /tmp/dg-sidebar-investigation-2026-09-20/inspect-graph-read-only.js <<'JS'
(() => {
  const api = window.roamAlphaAPI;
  const normalize = (value) => {
    if (Array.isArray(value)) return value.map(normalize);
    if (value && typeof value === 'object') {
      return Object.fromEntries(Object.entries(value).map(([key, item]) => [key.replace(/^:+/, ''), normalize(item)]));
    }
    return value;
  };
  const page = api.pull(
    '[:block/uid {:block/children [:block/uid :block/string :block/props :create/time :edit/time]}]',
    [':node/title', 'roam/js/discourse-graph']
  );
  if (!page) return {error: 'DG settings page not found'};
  const top = page[':block/children'] || [];
  const matching = (text) => top.filter((block) => block[':block/string'] === text);
  const propsOf = (block) => normalize(block?.[':block/props'] || {});
  const sidebar = matching('Left Sidebar')[0];
  const legacy = sidebar ? api.pull(
    '[{:block/children [:block/string {:block/children [:block/string]}]}]',
    [':block/uid', sidebar[':block/uid']]
  )?.[':block/children'] || [] : [];
  const currentUser = api.user.uid();
  const userIds = new Set([currentUser]);
  for (const block of legacy) {
    const label = block[':block/string'] || '';
    if (label.endsWith('/Personal-Section')) userIds.add(label.slice(0, -'/Personal-Section'.length));
  }
  const rows = [...userIds].filter(Boolean).map((userId) => {
    const oldBlocks = legacy.filter((block) => block[':block/string'] === userId + '/Personal-Section');
    const newBlocks = matching(userId);
    return {
      userId,
      currentUser: userId === currentUser,
      legacyPersonalBlockCount: oldBlocks.length,
      legacySectionCounts: oldBlocks.map((block) => (block[':block/children'] || []).length),
      propsPersonalBlockCount: newBlocks.length,
      propsSectionCounts: newBlocks.map((block) => {
        const sections = propsOf(block)['Left sidebar'];
        return Array.isArray(sections) ? sections.length : 'missing or invalid';
      })
    };
  });
  const featureFlags = matching('Feature Flags').map((block) => {
    const props = propsOf(block);
    return {
      uid: block[':block/uid'],
      useNewSettingsStore: props['Use new settings store'],
      propsDefaultMigrated: props['Props settings default migrated'],
      enableLeftSidebar: props['Enable left sidebar']
    };
  });
  const markers = ['Block props migrated', 'Block props migrated v2'].flatMap((label) => matching(label).map((block) => ({
    label,
    uid: block[':block/uid'],
    createdAt: block[':create/time'] ? new Date(block[':create/time']).toISOString() : null,
    editedAt: block[':edit/time'] ? new Date(block[':edit/time']).toISOString() : null
  })));
  const result = {
    currentUser, markers, featureFlags, users: rows,
    dom: {
      roamSidebarWrapperPresent: Boolean(document.querySelector('.starred-pages-wrapper')),
      dgRootPresent: Boolean(document.querySelector('#dg-left-sidebar-root')),
      dgPersonalContainerPresent: Boolean(document.querySelector('.personal-left-sidebar-sections'))
    },
    note: 'Read-only counts and markers. Does not inspect per-user extensionAPI migration markers. Duplicate settings blocks are reported rather than silently selected.'
  };
  console.table(rows);
  console.log('DG sidebar read-only inspection', result);
  return result;
})();
